import pathlib,json,subprocess,hashlib,gzip,shutil
root=pathlib.Path('/workspace/red-panda'); cache=root/'.cache/validation'; out=root/'docs/reference/phase17-integration'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
run=cache/'phase17-retry';status=json.loads((run/'full-status.json').read_text()); stable=json.loads((run/'source-stable.json').read_text())
assert len(status)==4 and all(x['exit']==0 for x in status) and stable['unchanged'],status
before=json.loads((run/'full-source-before.json').read_text());after=json.loads((run/'full-source-after.json').read_text());assert before==after
staged=set(subprocess.check_output(['git','ls-files','-z'],cwd=root).decode().split('\0'))
committed={p:h for p,h in before.items()if p in staged};native={p:h for p,h in before.items()if p.startswith('native/build/')};unused={p:h for p,h in before.items()if p not in staged and p not in native}
assert len(native)==18 and all(p.startswith('docs/reference/')for p in unused),list(unused)
for p,h in committed.items():assert hashlib.sha256(subprocess.check_output(['git','show',':'+p],cwd=root)).hexdigest()==h,p
out.mkdir(exist_ok=False)
for epoch in ['phase17','phase17-retry']:
 dest=out/('initial'if epoch=='phase17'else'accepted');dest.mkdir()
 for p in sorted((cache/epoch).iterdir()):
  if not p.is_file():continue
  if p.suffix=='.log':(dest/(p.name+'.gz')).write_bytes(gzip.compress(p.read_bytes(),mtime=0))
  else:shutil.copyfile(p,dest/p.name)
full=(run/'full.log').read_text();assert 'ℹ tests 1323' in full and 'ℹ pass 1323' in full and 'ℹ fail 0' in full
assert 'PureScript Puppeteer integration: 71 checks passed' in full
result={'baseCommit':subprocess.check_output(['git','rev-parse','HEAD'],cwd=root,text=True).strip(),'date':'2026-10-31','scope':'Independent URLPattern, media data/track values, Web Crypto, Worker Event/Abort/DOMException/Scheduler, device defaults, Cookie Store, Selection/Range, Web Locks, ElementInternals and source-profile fixture transport. No full browser/WPT/performance parity claim.','sourceSHA256':committed,'nativeBuildArtifactSHA256':native,'unusedPreexistingReferenceSHA256':unused,'unchangedObservedInputs':len(before),'committedSourceAndReferenceInputs':len(committed),'checks':status,'counts':{'javascript':1323,'purescript':71,'nativeDifferentialGroups':13},'firstRun':{'javascript':1323,'passed':1320,'failed':3,'status':json.loads((cache/'phase17/full-status.json').read_text()),'inputsUnchanged':True,'classification':[{'test':'Cookie Store cross-site frame','kind':'proxy setup mismatch','evidence':'initial/cookie-cross-diagnostic.log.gz','resolution':'Explicit NO_PROXY/no_proxy bypass for127.0.0.2 and127.255.1.2; exact same test passes, no browser source change'},{'test':'Nominal prefix Text sibling advance','kind':'old assertion contradicted by actual Native control','oldExpected':5,'actualNativeSequence':[50,20,0,0,0,0],'evidence':'initial/native-prefix-observation-v2.json','resolution':'Existing assertion corrected to measured Native0; initial about:blank-body setup failure retained separately'},{'test':'Worker codec state/error/dequeue events','kind':'real composition defect','resolution':'Only genuine jsdom EventTarget implementations use Window event dispatch; actual Worker backend uses its genuine VM Event/dispatch path','evidence':'initial/composition-fixes.log.gz','focusedPassing':27}]},'sourceReadiness':'Actual root load/complete up to2000ms, then fresh source2000/8000ms assertion budget; no fixed settle. Exact registrations/profile/bytes are observed.','native455Baseline':'451 verified passes and4 separately classified nonpasses; Native-only frozen epoch, not current candidate acceptance. Corrected-header and compare-position replays remain separate.','limits':['Complete455 candidate matrix not yet measured at this source','Native profile parity is not WPT or performance parity','Remaining Window symbol/heap/IDL differences, Worker Request.signal, full geometry/Unicode/layout and exotic custom-element rollback','Wider audio/media decoding, media playback, IndexedDB, Sanitizer, Payment, Web Animations and popup ownership remain isolated next-slice work','Additional protocol/resource isolation, full asynchronous deadlines, network/SameSite and permissions coverage remain incomplete'],'artifacts':{str(p.relative_to(out)):sha(p)for p in sorted(out.rglob('*'))if p.is_file()}}
(out/'validation.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({'checks':status,'observed':len(before),'committed':len(committed),'native':len(native),'unused':len(unused)}))
